"""Random request generator for differential testing."""
import json, math, random
import ref

TOPOS = [
    lambda r: ["leaf-spine", r.randint(2, 5), r.randint(1, 3)],
    lambda r: ["clos", 4, r.choice(["tor", "pod"]), r.randint(0, 1)],
    lambda r: ["clos", 6, r.choice(["tor", "pod"]), r.randint(0, 1)],
    lambda r: ["torus2d", r.randint(3, 5), r.choice(["host", "row"])],
    lambda r: ["torus3d", 3, r.choice(["host", "line"])],
    lambda r: ["dragonfly", 2, 1, 1, r.choice(["router", "group", "target"])],
    lambda r: ["dragonfly", 4, 1, 3, r.choice(["router", "group", "target"])],
    lambda r: ["dragonfly", 3, 2, 1, r.choice(["router", "group", "target"])],
    lambda r: ["dragonfly-plus", r.randint(2, 3), r.randint(1, 2), r.randint(1, 2), 1,
               r.randint(0, 1), r.choice(["group", "tor"])],
    lambda r: ["dragonfly-plus", 2, 2, 1, 1, 0, r.choice(["group", "tor"])],
]


def node_count(topo):
    if topo[0] == 'leaf-spine':
        return topo[1] + topo[2]
    if topo[0] == 'clos':
        return topo[1] * topo[1]
    if topo[0] == 'torus2d':
        return topo[1] ** 2
    if topo[0] == 'torus3d':
        return topo[1] ** 3
    if topo[0] == 'dragonfly':
        return topo[1] * topo[2]
    return topo[1] * (topo[2] + topo[3])


def gen_session(rng, structured=None):
    topo = rng.choice(TOPOS)(rng)
    n, tpls = ref.build_topology(topo)
    ntpl = len(tpls)
    if structured is None:
        structured = rng.random() < 0.8
    G = rng.randint(1, 6)
    D = rng.randint(0, 12)
    groups = [[rng.randint(1, 64), rng.randint(1, 10 ** 12)] for _ in range(G)]
    tasks = []
    if structured:
        # per group choose one (domain,class); all member tasks match it
        gpair = {}
        bydom = {}
        for i, tp in enumerate(tpls):
            bydom.setdefault(tp[3], []).append(i)
        for g in range(G):
            dom = rng.choice(list(bydom.keys()))
            gpair[g] = (dom, rng.randint(0, 4))
        cnt = [0] * G
        for _ in range(D):
            g = rng.randrange(G)
            dom, cls = gpair[g]
            tasks.append([rng.choice(bydom[dom]), g, rng.randint(1, 30), cls, rng.randint(0, 1)])
            cnt[g] += 1
        for g in range(G):
            q, b = groups[g]
            if cnt[g] == 0:
                if rng.random() < 0.3:
                    groups[g] = [0, b]
                continue
            load = sum(t[2] for t in tasks if t[1] == g)
            # ensure quota>0 and load<=quota*budget
            q = rng.randint(1, 64)
            b = rng.randint(1, 10 ** 12)
            if load > q * b:
                b = load // q + 1
            groups[g] = [q, b]
        r = ref.Ref(n, tpls, tasks, groups, [0] * n)
        d = r.derive(tasks, groups and [g[0] for g in groups] or [], [g[1] for g in groups], [0] * n)
        caps = []
        for v in range(n):
            need = d['usage'][v]
            caps.append(need + rng.randint(0, 12))
    else:
        for _ in range(D):
            tasks.append([rng.randrange(ntpl), rng.randrange(G), rng.randint(1, 30),
                          rng.randint(0, 4), rng.randint(0, 1)])
        caps = [rng.randint(0, 40) for _ in range(n)]

    def q():
        return {"groups": [rng.randrange(G) for _ in range(rng.randint(0, 4))],
                "nodes": [rng.randrange(n) for _ in range(rng.randint(0, 4))],
                "tasks": [rng.randrange(D) for _ in range(rng.randint(0, 4))] if D else []}
    txs = []
    for _ in range(rng.randint(0, 12)):
        edits = []
        for _ in range(rng.randint(0, 8)):
            op = rng.choice(['move', 'weight', 'class', 'bind', 'pin', 'quota', 'budget', 'cap'])
            if op in ('move', 'weight', 'class', 'bind', 'pin'):
                if D == 0:
                    continue
                idx = rng.randrange(D)
                if op == 'move':
                    val = rng.randrange(G)
                elif op == 'weight':
                    val = rng.randint(1, 30)
                elif op == 'class':
                    val = rng.randint(0, 4)
                elif op == 'bind':
                    val = rng.randrange(ntpl)
                else:
                    val = rng.randint(0, 1)
            elif op in ('quota', 'budget'):
                idx = rng.randrange(G)
                val = rng.randint(0, 64) if op == 'quota' else rng.randint(1, 10 ** 12)
            else:
                idx = rng.randrange(n)
                val = rng.randint(0, 40)
            edits.append([op, idx, val])
        txs.append({"revision": rng.randint(0, 5), "edits": edits, "query": q()})
    return {"topology": topo, "caps": caps, "groups": groups, "tasks": tasks,
            "query": q(), "transactions": txs}


def gen_request(seed, structured_prob=0.8):
    rng = random.Random(seed)
    out = []
    for _ in range(rng.randint(0, 3)):
        s = structured_prob if structured_prob is not None else None
        out.append(gen_session(rng, rng.random() < s if s is not None else None))
    return {"version": 2, "sessions": out}
PYEOF
